const { buildSpellCheckMenuSections } = require('../integrations/spellcheck');

function composeMenuSections(sections) {
    const populatedSections = sections.filter((section) => section.length > 0);
    const template = [];

    for (const section of populatedSections) {
        if (template.length > 0) template.push({ type: 'separator' });
        template.push(...section);
    }

    return template;
}

/** Build native editing commands for the clicked renderer text context. */
function buildEditingMenuSection(params, clipboard) {
    if (!clipboard) throw new Error('Clipboard dependency is required for the text context menu');

    const { canCopy = false, canCut = false, canPaste = false } = params.editFlags ?? {};
    const canCopyAsText = !!params.selectionText;
    if (!canCopy && !canCopyAsText && !canCut && !canPaste) return [];

    return [
        { enabled: canCut, role: 'cut' },
        { enabled: canCopy, role: 'copy' },
        {
            click: () => clipboard.writeText(params.selectionText),
            enabled: canCopyAsText,
            label: 'Copy as Text',
        },
        { enabled: canPaste, role: 'paste' },
    ];
}

function buildTextContextMenuTemplate(webContents, params, options) {
    const {
        activeLanguages = [],
        availableLanguages = [],
        clipboard,
        onSetLanguages,
    } = options;
    const { correctionItems, languageItems } = buildSpellCheckMenuSections(webContents, params, {
        activeLanguages,
        availableLanguages,
        onSetLanguages,
    });
    const editingItems = buildEditingMenuSection(params, clipboard);

    return composeMenuSections([correctionItems, editingItems, languageItems]);
}

/** Register one owner for Electron text editing and spelling context menus. */
function registerTextContextMenu(webContents, options) {
    const {
        buildMenu,
        clipboard,
        getActiveLanguages,
        getAvailableLanguages,
        setActiveLanguages,
    } = options;
    if (typeof buildMenu !== 'function') throw new Error('Menu builder dependency is required for the text context menu');

    webContents.on('context-menu', (_event, params) => {
        const template = buildTextContextMenuTemplate(webContents, params, {
            activeLanguages: getActiveLanguages?.() ?? [],
            availableLanguages: getAvailableLanguages?.() ?? [],
            clipboard,
            onSetLanguages: setActiveLanguages,
        });
        if (template.length === 0) return;

        buildMenu(template).popup();
    });
}

module.exports = {
    buildEditingMenuSection,
    buildTextContextMenuTemplate,
    registerTextContextMenu,
};

/**
 * Right-click spelling corrections for editable renderer content. Chromium's
 * spellchecker already underlines misspelled words; this adds the context menu
 * that lets the user pick a suggestion (or teach the dictionary a new word),
 * plus a "Spelling Languages" submenu for switching the checked languages. The
 * suggestion items only appear when the click lands on a misspelled word; the
 * language submenu appears for any editable target so it stays reachable.
 */

const SPELL_CHECKER_LANGUAGES_STORE_KEY = 'spellCheckerLanguages';

let displayNames = null;
function languageLabel(code) {
    try {
        if (!displayNames) displayNames = new Intl.DisplayNames(['en'], { type: 'language' });

        return displayNames.of(code) ?? code;
    } catch {
        return code;
    }
}

function buildLanguageSubmenu(availableLanguages, activeLanguages, onSetLanguages) {
    const active = new Set(activeLanguages);

    // Single-select: picking a language replaces the checked set so switching to
    // another language actually re-runs the check against that language alone.
    return availableLanguages.map((code) => ({
        checked: active.has(code),
        click: () => onSetLanguages([code]),
        label: languageLabel(code),
        type: 'radio',
    }));
}

function buildSpellCheckMenuSections(webContents, params, options = {}) {
    const { availableLanguages = [], activeLanguages = [], onSetLanguages } = options;
    const correctionItems = [];
    const languageItems = [];

    if (params.misspelledWord) {
        for (const suggestion of params.dictionarySuggestions ?? []) {
            correctionItems.push({ label: suggestion, click: () => webContents.replaceMisspelling(suggestion) });
        }

        correctionItems.push({
            label: 'Add to Dictionary',
            click: () => webContents.session.addWordToSpellCheckerDictionary(params.misspelledWord),
        });
    }

    if (params.isEditable && onSetLanguages && availableLanguages.length > 0) {
        languageItems.push({
            label: 'Spelling Languages',
            submenu: buildLanguageSubmenu(availableLanguages, activeLanguages, onSetLanguages),
        });
    }

    return { correctionItems, languageItems };
}

/**
 * Chromium does not re-spellcheck text that is already rendered when the
 * language set changes; squiggles refresh only when the editable surface
 * reloads. Toggling the spellcheck attribute off and back on (with a frame in
 * between) plus a blur/focus of the active element forces a re-check without
 * remounting the editor.
 */
const REFRESH_SPELL_CHECK_SCRIPT = `(() => {
    const editables = document.querySelectorAll('[contenteditable], textarea, input')
    for (const element of editables) element.spellcheck = false
    requestAnimationFrame(() => {
        for (const element of editables) element.spellcheck = true
        const active = document.activeElement
        if (active && typeof active.blur === 'function') {
            active.blur()
            active.focus()
        }
    })
})()`;

function refreshSpellCheck(webContents) {
    if (webContents.isDestroyed()) return;

    webContents.executeJavaScript(REFRESH_SPELL_CHECK_SCRIPT, true).catch(() => {});
}

/** Re-apply the user's persisted language choice, ignoring any codes the platform no longer supports. */
function applyStoredSpellCheckerLanguages(session, storedLanguages) {
    if (!Array.isArray(storedLanguages)) return;

    const available = new Set(session.availableSpellCheckerLanguages);
    const languages = storedLanguages.filter((code) => available.has(code));
    if (languages.length > 0) session.setSpellCheckerLanguages(languages);
}

module.exports = {
    REFRESH_SPELL_CHECK_SCRIPT,
    SPELL_CHECKER_LANGUAGES_STORE_KEY,
    applyStoredSpellCheckerLanguages,
    buildSpellCheckMenuSections,
    refreshSpellCheck,
};

const { app, BrowserWindow, Menu, clipboard, dialog, ipcMain, nativeTheme, shell } = require('electron');
const { existsSync } = require('node:fs');
const https = require('node:https');
const path = require('node:path');

const desktopEnvironmentPath = app.isPackaged
    ? path.join(process.resourcesPath, '.env')
    : path.join(__dirname, '.env');
if (existsSync(desktopEnvironmentPath)) process.loadEnvFile(desktopEnvironmentPath);

const Store = require('electron-store');
const { readDesktopConfig, resolveBridgeAllowedOrigins, saveDesktopConfig } = require('./src/shell/config');
const { AgentRunnerService } = require('./src/actions/agent/agent_runner_service');
const { CodexRuntimeService } = require('./src/actions/agent/codex_runtime_service');
const { AgentExecutableResolver, loadAgentExecutableAvailability } = require('./src/actions/agent/agent_executable_availability');
const { ActionSchedulerService } = require('./src/actions/action/action_scheduler_service');
const { ActionRunnerService } = require('./src/actions/action/action_runner_service');
const diffService = require('./src/git/diff_service');
const { createLocalBridgeDispatch } = require('./src/shell/local_bridge_dispatch');
const localGitService = require('./src/git/local_git_service');
const { RemoteControlService } = require('./src/integrations/remote_control_service');
const remarkableService = require('./src/integrations/remarkable_service');
const { WorktreeService } = require('./src/git/worktree_service');
const { MergeConflictService } = require('./src/git/merge_conflict_service');
const { ActionWorktreeRunService } = require('./src/actions/action/action_worktree_run_service');
const { captureError, flush, registerProcessErrorHandlers, startElectronTelemetry, trackEvent } = require('./src/integrations/telemetry');
const { THEME_MODE_STORE_KEY, resolveThemeMode, resolveTitleBarOverlay } = require('./src/shell/theme');
const { registerNavigationGuards, resolveRendererStaticDir, resolveRendererTarget } = require('./src/shell/renderer_security');
const { registerTextContextMenu } = require('./src/shell/text_context_menu');
const {
    SPELL_CHECKER_LANGUAGES_STORE_KEY,
    applyStoredSpellCheckerLanguages,
    refreshSpellCheck,
} = require('./src/integrations/spellcheck');
const {
    CONFIG_GET_DESKTOP_CHANNEL,
    CONFIG_SET_DESKTOP_CHANNEL,
    LIFECYCLE_FLUSH_DONE_CHANNEL,
    LIFECYCLE_FLUSH_REQUEST_CHANNEL,
    LOCAL_BRIDGE_EVENT_CHANNEL,
    LOCAL_BRIDGE_INVOKE_CHANNEL,
    LOCAL_BRIDGE_SUBSCRIBE_CHANNEL,
    LOCAL_BRIDGE_UNSUBSCRIBE_CHANNEL,
    REMARKABLE_IMPORT_FILES_CHANNEL,
    REMARKABLE_LIST_IMAGE_FILES_CHANNEL,
            sandbox: true,
        },
    });

    registerNavigationGuards(window.webContents, rendererTarget.trustedLocation, (url) => shell.openExternal(url));
    const spellCheckerSession = window.webContents.session;
    applyStoredSpellCheckerLanguages(spellCheckerSession, store.get(SPELL_CHECKER_LANGUAGES_STORE_KEY));
    registerTextContextMenu(window.webContents, {
        buildMenu: (template) => Menu.buildFromTemplate(template),
        clipboard,
        getActiveLanguages: () => spellCheckerSession.getSpellCheckerLanguages(),
        getAvailableLanguages: () => spellCheckerSession.availableSpellCheckerLanguages,
        setActiveLanguages: (languages) => {
            spellCheckerSession.setSpellCheckerLanguages(languages);
            store.set(SPELL_CHECKER_LANGUAGES_STORE_KEY, languages);
            refreshSpellCheck(window.webContents);
        },
    });
    // A newly selected language may still be downloading its dictionary when
    // the switch happens; refresh again once Chromium finishes loading it.
    const handleDictionaryInitialized = () => refreshSpellCheck(window.webContents);
    spellCheckerSession.on('spellcheck-dictionary-initialized', handleDictionaryInitialized);
    window.on('closed', () => spellCheckerSession.removeListener('spellcheck-dictionary-initialized', handleDictionaryInitialized));
    if (rendererTarget.type === 'file') {
        void window.loadFile(rendererTarget.filePath);
    } else {
        void window.loadURL(rendererTarget.url);
    }

    if (!app.isPackaged) {
        window.webContents.openDevTools();
    }

    return window;
}

